        self.aapl_rsi_14 = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.SetWarmUp(200, Resolution.Daily)

        self.spy_lot = 0
        self.aapl_lot = 0

        self.spy_order_pending = False
        self.aapl_order_pending = False
        self.pending_orders = {}

        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_rsi_14 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        if not all(symbol in data.Bars for symbol in self.symbols):
            return

        if not (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
            and self.previous_aapl_rsi_14 is not None
        ):
            return

        spy_close = data.Bars[self.spy].Close
        aapl_rsi = self.aapl_rsi_14.Current.Value

        spy_buy_reason = (
            self.previous_spy_sma_200 <= self.previous_spy_sma_200
            and spy_close > self.spy_sma_200.Current.Value
            and self.previous_spy_sma_200 <= self.previous_spy_sma_200
        )

        spy_buy_reason = (
            self.previous_spy_sma_200 is not None
            and self.spy_sma_200.Current.Value > self.previous_spy_sma_200
            and spy_close > self.spy_sma_200.Current.Value
        )

        spy_sell_reason = (
            self.previous_spy_sma_50 is not None
            and self.spy_sma_50.Current.Value < self.previous_spy_sma_50
            and spy_close < self.spy_sma_50.Current.Value
        )

        aapl_sell_reason = (
            self.previous_aapl_rsi_14 <= 60
            and aapl_rsi > 60
        )

        # Evaluate sells before buys.
        if (
            self.spy_lot > 0
            and not self.spy_order_pending
            and spy_sell_reason
        ):
            self._liquidate_lot(self.spy, "SPY")

        if (
            self.aapl_lot > 0
            and not self.aapl_order_pending
            and aapl_sell_reason
        ):
            self._liquidate_lot(self.aapl, "AAPL")

        if (
            self.spy_lot == 0
            and not self.spy_order_pending
            and spy_buy_reason
        ):
            close = data.Bars[self.spy].Close
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            quantity = int(target_value / close)

            if quantity > 0:
                ticket = self.MarketOrder(self.spy, quantity)
                self.pending_orders[ticket.OrderId] = ("SPY", "buy")
                self.spy_order_pending = True

        if (
            self.aapl_lot == 0
            and not self.aapl_order_pending
            and self.aapl_red_streak >= 3
        ):
            close = data.Bars[self.aapl].Close
            available_cash = self.Portfolio.Cash

            if available_cash >= 20000:
                quantity = int(20000 / close)

                if quantity > 0:
                    ticket = self.MarketOrder(self.aapl, quantity)
                    self.pending_orders[ticket.OrderId] = ("AAPL", "buy")
                    self.aapl_order_pending = True

    def _update_market_state(self, data: Slice):
        if self.spy_sma_200.IsReady:
            self.previous_spy_sma_200 = self.spy_sma_200.Current.Value

        if self.spy_sma_50.IsReady:
            self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        if self.aapl_rsi_14.IsReady:
            self.previous_aapl_rsi_14 = self.aapl_rsi_14.Current.Value

        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

    def _liquidate_lot(self, symbol, strategy_name):
        lot = self.spy_lot if strategy_name == "SPY" else self.aapl_lot

        if lot <= 0:
            return

        ticket = self.MarketOrder(symbol, -lot)
        self.pending_orders[ticket.OrderId] = (strategy_name, "sell")

        if strategy_name == "SPY":
            self.spy_order_pending = True
        else:
            self.aapl_order_pending = True

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.OrderId not in self.pending_orders:
            return

        strategy_name, action = self.pending_orders[orderEvent.OrderId]

        if orderEvent.Status == OrderStatus.Filled:
            fill_quantity = orderEvent.FillQuantity

            if strategy_name == "SPY":
                if action == "buy":
                    self.spy_lot += fill_quantity
                else:
                    self.spy_lot = max(0, self.spy_lot + fill_quantity)

                self.spy_order_pending = False

            else:
                if action == "buy":
                    self.aapl_lot += fill_quantity
                else:
                    self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

                self.aapl_order_pending = False

            del self.pending_orders[orderEvent.OrderId]

        elif orderEvent.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None_,
        ):
            if strategy_name == "SPY":
                self.spy_order_pending = False
            else:
                self.aapl_order_pending = False

            del self.pending_orders[orderEvent.OrderId]

